// Lee la respuesta de la IA y la deja lista para guardar. Si no hay riesgos, se guarda [] (limpia las alertas).
const s = String($input.first().json.text || '').replace(/```(json)?/gi, '');
let alertas = [];
const ini = s.indexOf('[');
const fin = s.lastIndexOf(']');
if (ini >= 0 && fin > ini) alertas = JSON.parse(s.slice(ini, fin + 1));
const validos = new Set(JSON.parse($('Riesgos de hoy').first().json.riesgos_json).map((r) => r.usuario_id));
alertas = alertas.filter((a) => a && a.titulo && (a.usuario_id == null || validos.has(Number(a.usuario_id))));
return [{ json: { total: alertas.length, alertas: JSON.stringify(alertas) } }];
